insert into public.arena_matches(code,mode,topic,question_count,created_by,game_type,game_settings,expires_at) values(public.arena_make_code(),coalesce(nullif(p_mode,''),'duel'),nullif(trim(p_topic),''),q_count,auth.uid(),g,s,now()+interval '30 minutes') returning * into m;
insert into public.arena_players(match_id,user_id,display_name,rating) values(m.id,auth.uid(),n,coalesce((select rating from public.arena_ratings where user_id=auth.uid()),1000));
insert into public.arena_match_questions(match_id,question_index,question_id) select m.id,row_number() over(order by random())-1,id from public.arena_question_bank where active and (m.topic is null or topic=m.topic) order by random() limit q_count;
insert into public.arena_answers(match_id,player_id,question_index,answer_index,is_correct,response_ms,points) values(p_match_id,p_player_id,p_question_index,p_answer_index,v_correct_now,v_response,v_points); update public.arena_players set score=score+v_points,correct=correct+case when v_correct_now then 1 else 0 end,answered=answered+1 where id=p_player_id;
