-- Distribution hardening migration. Production was applied with the same SQL.
-- Seed/refresh the server-authoritative Arena bank from the canonical v61 question set.
on conflict(question_key) do update set topic=excluded.topic,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,difficulty=excluded.difficulty,active=true,updated_at=now();

create or replace function public.arena_create_match(p_mode text default 'duel',p_topic text default null,p_question_count integer default 10) returns public.arena_matches language plpgsql security definer set search_path to 'public','pg_catalog' as $function$
declare m public.arena_matches; n text; g text; s jsonb; q_count integer; begin
if auth.uid() is null then raise exception 'auth_required'; end if;
g:=coalesce((select game_type from public.arena_game_preferences where user_id=auth.uid()),'ten'); s:=coalesce((select settings from public.arena_game_preferences where user_id=auth.uid()),'{}'::jsonb); n:=coalesce((select raw_user_meta_data->>'display_name' from auth.users where id=auth.uid()),(select raw_user_meta_data->>'full_name' from auth.users where id=auth.uid()),'Oyuncu'); q_count:=least(greatest(coalesce(p_question_count,10),5),20);
perform public.arena_sync_profile(n); insert into public.arena_ratings(user_id) values(auth.uid()) on conflict(user_id) do nothing;
if (select count(*) from public.arena_match_questions where match_id=m.id)<q_count then delete from public.arena_match_questions where match_id=m.id; insert into public.arena_match_questions(match_id,question_index,question_id) select m.id,row_number() over(order by random())-1,id from public.arena_question_bank where active order by random() limit q_count; end if; return m; end;$function$;

create or replace function public.arena_submit_answer(p_match_id uuid,p_player_id uuid,p_question_index integer,p_answer_index integer,p_is_correct boolean default null,p_response_ms integer default null,p_points integer default null) returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare v_uid uuid:=auth.uid(); v_qid uuid; v_correct smallint; v_correct_now boolean; v_points integer; v_response integer; v_match public.arena_matches; v_players integer; v_answered integer; v_new_index integer; v_done boolean; v_winner uuid; begin
if v_uid is null then raise exception 'authentication required'; end if; select * into v_match from public.arena_matches where id=p_match_id for update; if not found or v_match.status not in('active','waiting') then raise exception 'match unavailable'; end if; if not exists(select 1 from public.arena_players where id=p_player_id and match_id=p_match_id and user_id=v_uid) then raise exception 'player mismatch'; end if; if p_question_index<>v_match.current_question then raise exception 'stale_question'; end if; select question_id into v_qid from public.arena_match_questions where match_id=p_match_id and question_index=p_question_index; if v_qid is null then raise exception 'server question not configured'; end if; select correct_index into v_correct from public.arena_question_bank where id=v_qid and active; if v_correct is null then raise exception 'question unavailable'; end if; if p_answer_index<0 or p_answer_index>5 then raise exception 'invalid answer'; end if; if exists(select 1 from public.arena_answers where player_id=p_player_id and question_index=p_question_index) then raise exception 'answer already submitted'; end if;
if v_match.question_started_at is null then update public.arena_matches set question_started_at=now(),last_activity_at=now() where id=p_match_id returning * into v_match; end if; v_correct_now:=p_answer_index=v_correct; v_response:=greatest(0,least(extract(epoch from(clock_timestamp()-v_match.question_started_at))::integer,120000)); v_points:=case when v_correct_now then greatest(10,1000-least(v_response,99000)/100) else 0 end;
select count(*) into v_players from public.arena_players where match_id=p_match_id; select count(*) into v_answered from public.arena_answers where match_id=p_match_id and question_index=p_question_index; v_new_index:=p_question_index+1; v_done:=v_new_index>=v_match.question_count;
if v_answered>=v_players then if v_done then select user_id into v_winner from public.arena_players where match_id=p_match_id order by score desc,correct desc,answered asc limit 1; update public.arena_matches set status='finished',finished_at=now(),current_question=v_new_index,current_round=v_new_index,winner_user_id=v_winner,question_started_at=null,last_activity_at=now(),result_applied=true where id=p_match_id; else update public.arena_matches set current_question=v_new_index,current_round=v_new_index,question_started_at=now(),last_activity_at=now() where id=p_match_id; end if; else update public.arena_matches set last_activity_at=now() where id=p_match_id; end if;
return jsonb_build_object('accepted',true,'is_correct',v_correct_now,'points',v_points,'response_ms',v_response,'current_question',case when v_answered>=v_players then v_new_index else p_question_index end,'finished',v_done and v_answered>=v_players,'winner_user_id',v_winner); end;$function$;

revoke execute on function public.get_learning_dashboard() from anon;
revoke execute on function public.record_learning_answer(text,boolean,text,integer) from anon;
grant execute on function public.get_learning_dashboard() to authenticated;
grant execute on function public.record_learning_answer(text,boolean,text,integer) to authenticated;